import { globSync } from 'glob';
import { statSync, readFileSync } from 'fs';
import { homedir } from 'os';
import * as pathLib from 'path';
export const DEFAULT_UPLOAD_CONCURRENCY = 4;
export const uploadUrl = (url) => {
    const templateMarkerPos = url.indexOf('{');
    if (templateMarkerPos > -1) {
        return url.substring(0, templateMarkerPos);
    }
    return url;
};
export const releaseBody = (config) => {
    if (config.input_body_path) {
        try {
            return readFileSync(config.input_body_path, 'utf8');
        }
        catch (err) {
            console.warn(`⚠️ Failed to read body_path "${config.input_body_path}" (${err?.code ?? 'ERR'}). Falling back to 'body' input.`);
        }
    }
    return config.input_body;
};
const smartSplit = (input) => {
    const result = [];
    let current = '';
    let braceDepth = 0;
    for (const ch of input) {
        if (ch === '{') {
            braceDepth++;
        }
        if (ch === '}') {
            braceDepth--;
        }
        if (ch === ',' && braceDepth === 0) {
            if (current.trim()) {
                result.push(current.trim());
            }
            current = '';
        }
        else {
            current += ch;
        }
    }
    if (current.trim()) {
        result.push(current.trim());
    }
    return result;
};
export const parseInputFiles = (files) => {
    return files
        .split(/\r?\n/)
        .flatMap(line => smartSplit(line))
        .filter(pat => pat.trim() !== '');
};
const parseMakeLatest = (value) => {
    if (value === 'true' || value === 'false' || value === 'legacy') {
        return value;
    }
    return undefined;
};
const parseOnTagConflict = (value) => {
    return value?.trim() === 'fail' ? 'fail' : 'update';
};
const parseToken = (env) => {
    const inputToken = env.INPUT_TOKEN?.trim();
    if (inputToken) {
        return inputToken;
    }
    return env.GITHUB_TOKEN?.trim() || '';
};
const parseConcurrency = (raw) => {
    if (!raw) {
        return DEFAULT_UPLOAD_CONCURRENCY;
    }
    const trimmed = raw.trim();
    if (trimmed === '') {
        return DEFAULT_UPLOAD_CONCURRENCY;
    }
    const parsed = Number(trimmed);
    if (!Number.isFinite(parsed) || parsed < 1) {
        console.warn(`⚠️ Invalid concurrency "${raw}", falling back to default (${DEFAULT_UPLOAD_CONCURRENCY}).`);
        return DEFAULT_UPLOAD_CONCURRENCY;
    }
    return Math.floor(parsed);
};
export const parseConfig = (env) => {
    return {
        github_token: parseToken(env),
        github_ref: env.GITHUB_REF || '',
        github_repository: env.INPUT_REPOSITORY || env.GITHUB_REPOSITORY || '',
        input_name: env.INPUT_NAME,
        input_tag_name: normalizeTagName(env.INPUT_TAG_NAME?.trim()),
        input_body: env.INPUT_BODY,
        input_body_path: env.INPUT_BODY_PATH,
        input_files: parseInputFiles(env.INPUT_FILES || ''),
        input_working_directory: env.INPUT_WORKING_DIRECTORY || undefined,
        input_overwrite_files: env.INPUT_OVERWRITE_FILES ? env.INPUT_OVERWRITE_FILES === 'true' : undefined,
        input_draft: env.INPUT_DRAFT ? env.INPUT_DRAFT === 'true' : undefined,
        input_preserve_order: env.INPUT_PRESERVE_ORDER ? env.INPUT_PRESERVE_ORDER === 'true' : undefined,
        input_prerelease: env.INPUT_PRERELEASE ? env.INPUT_PRERELEASE === 'true' : undefined,
        input_fail_on_unmatched_files: env.INPUT_FAIL_ON_UNMATCHED_FILES === 'true',
        input_fail_on_asset_upload_issue: env.INPUT_FAIL_ON_ASSET_UPLOAD_ISSUE === 'true',
        input_target_commitish: env.INPUT_TARGET_COMMITISH || undefined,
        input_discussion_category_name: env.INPUT_DISCUSSION_CATEGORY_NAME || undefined,
        input_generate_release_notes: env.INPUT_GENERATE_RELEASE_NOTES === 'true',
        input_previous_tag: env.INPUT_PREVIOUS_TAG?.trim() || undefined,
        input_append_body: env.INPUT_APPEND_BODY === 'true',
        input_make_latest: parseMakeLatest(env.INPUT_MAKE_LATEST),
        input_concurrency: parseConcurrency(env.INPUT_CONCURRENCY),
        input_on_tag_conflict: parseOnTagConflict(env.INPUT_ON_TAG_CONFLICT),
        input_draft_during_upload: env.INPUT_DRAFT_DURING_UPLOAD?.trim() !== 'false'
    };
};
export const normalizeGlobPattern = (pattern, platform = process.platform) => {
    if (platform === 'win32') {
        return pattern.replace(/\\/g, '/');
    }
    return pattern;
};
export const expandHomePattern = (pattern, homeDirectory = homedir()) => {
    if (pattern === '~') {
        return homeDirectory;
    }
    if (pattern.startsWith('~/') || pattern.startsWith('~\\')) {
        return pathLib.join(homeDirectory, pattern.slice(2));
    }
    return pattern;
};
export const normalizeFilePattern = (pattern, platform = process.platform, homeDirectory = homedir()) => {
    return normalizeGlobPattern(expandHomePattern(pattern, homeDirectory), platform);
};
export const paths = (patterns, cwd) => {
    return patterns.reduce((acc, pattern) => {
        const matches = globSync(normalizeFilePattern(pattern), { cwd, dot: true, absolute: false });
        const resolved = matches
            .map(p => (cwd && !pathLib.isAbsolute(p) ? pathLib.join(cwd, p) : p))
            .filter(p => {
            try {
                return statSync(p).isFile();
            }
            catch {
                return false;
            }
        });
        return acc.concat(resolved);
    }, []);
};
export const unmatchedPatterns = (patterns, cwd) => {
    return patterns.reduce((acc, pattern) => {
        const matches = globSync(normalizeFilePattern(pattern), { cwd, dot: true, absolute: false });
        const files = matches.filter(p => {
            try {
                const full = cwd && !pathLib.isAbsolute(p) ? pathLib.join(cwd, p) : p;
                return statSync(full).isFile();
            }
            catch {
                return false;
            }
        });
        return acc.concat(files.length === 0 ? [pattern] : []);
    }, []);
};
export const isTag = (ref) => {
    return ref.startsWith('refs/tags/');
};
export const normalizeTagName = (tag) => {
    if (!tag) {
        return tag;
    }
    return isTag(tag) ? tag.replace('refs/tags/', '') : tag;
};
export const alignAssetName = (assetName) => {
    return assetName.replace(/ /g, '.');
};
